/* ---------------- 上傳紀錄表登錄結果（新版督導紀錄頁） ----------------
 * args: { id, score, defects:[{text, code, level, points}], content:{…紀錄表解析內容}, info:{欄位: 值}, file:{name, mimeType, base64}, force }
 * 1. 成績與缺失寫回（覆蓋該案原有缺失）；扣點以紀錄表為準
 * 2. 勾選要更新的工程基本資料寫回案件
 * 3. 紀錄表原檔存到擁有者雲端硬碟「督導紀錄檔案」資料夾，登記於「紀錄檔」表，之後可在系統內下載
 */
const DJ_INFO_FIELDS = ['所屬計畫', '縣市鄉鎮', '發包預算', '契約金額', '設計單位', '監造單位', '專案管理單位', '承包商', '開工日期', '委員1', '委員2', '領隊', '工作人員'];
function apiDjSaveRecord(args, user) {
  const lock = LockService.getScriptLock();
  lock.waitLock(30000);
  try {
    const c = readTable_('案件').find(x => x.案件編號 === args.id);
    if (!c) throw new Error('找不到案件 ' + args.id);
    if (c.狀態 === ST_CANCEL || c.狀態 === ST_VOID) throw new Error('此案件' + c.狀態 + '，不可登錄結果');
    const score = String(args.score == null ? '' : args.score).trim();
    if (score && score !== '不計分' && (isNaN(Number(score)) || Number(score) < 0 || Number(score) > 100)) throw new Error('分數格式不正確：' + score);
    const all = readTable_('缺失');
    const mine = all.filter(d => d.案件編號 === c.案件編號);
    if ((mine.length || (c.成績 !== '' && c.成績 != null)) && !args.force) {
      return { needConfirm: true, existing: mine.length, oldScore: String(c.成績 == null ? '' : c.成績) };
    }
    const now = nowStr_();
    // 原檔先存（失敗就不寫資料）
    let fileRow = null;
    if (args.file && args.file.base64) {
      const f = args.file, name = String(f.name || '紀錄表').replace(/[\\/:*?"<>|]/g, '_');
      if (f.base64.length > 27000000) throw new Error('檔案太大（上限約 20MB）');
      const created = driveCreate_({ name: c.案件編號 + '_' + name, parents: [djFolder_()] }, f.base64, f.mimeType || 'application/octet-stream');
      fileRow = { 案件編號: c.案件編號, 檔名: name, 類型: String(f.mimeType || ''), 檔案ID: created.id, 大小: Math.round(f.base64.length * 3 / 4), 上傳者: user.Email, 上傳時間: now };
    }
    const rows = (args.defects || []).filter(d => String(d.text || '').trim()).map((d, i) => {
      const code = String(d.code || '').trim(), level = String(d.level || '').trim();
      let text = String(d.text).trim();
      if (code && text.indexOf(code) < 0) text = text.replace(/[。\s]*$/, '。') + (level ? '【' + level + '】' : '') + '(' + code + ')';
      const p = parseDefect_(text);
      const pts = d.points === '' || d.points == null || isNaN(Number(d.points)) ? p.points : Number(d.points);
      return { 案件編號: c.案件編號, 序號: i + 1, 缺失紀錄: text, 缺失代碼: code || p.code, 缺失等級: level || p.level, 扣點: pts,
        委員: '', 原日期: c.日期, 原工程名稱: c.工程名稱, 資料來源: '紀錄表上傳', 修改者: user.Email, 修改時間: now };
    });
    if (args.content) saveRecordContent_(c.案件編號, args.content, user.Email, now);
    const keep = all.filter(d => d.案件編號 !== c.案件編號).map(d => { delete d._row; return d; });
    replaceTable_('缺失', keep.concat(rows));
    const before = Object.assign({}, c);
    c.成績 = score === '' ? '' : (score === '不計分' ? score : Number(score));
    c.缺失數 = rows.length || '';
    const info = args.info || {}, changed = {};
    Object.keys(info).forEach(k => {
      if (DJ_INFO_FIELDS.indexOf(k) < 0) return;
      let v = String(info[k] == null ? '' : info[k]).trim();
      if (k === '發包預算' || k === '契約金額') { const n = Number(v.replace(/,/g, '')); if (v && isNaN(n)) return; v = v ? n : ''; }
      if (k === '開工日期') v = ymd_(v);
      if (String(c[k] == null ? '' : c[k]) !== String(v)) { changed[k] = [c[k] == null ? '' : c[k], v]; c[k] = v; }
    });
    derive_(c, readTable_('國定假日').map(h => h.日期));
    c.修改者 = user.Email; c.修改時間 = now;
    writeRow_('案件', c);
    if (fileRow) appendRows_('紀錄檔', [fileRow]);
    log_(user.Email, '登錄結果（紀錄表）', c.案件編號, Object.assign({ 成績: [before.成績, c.成績], 缺失數: [before.缺失數 || 0, rows.length], 原缺失筆數: mine.length }, changed, fileRow ? { 原檔: fileRow.檔名 } : {}));
    return { ok: true, case: clean_(c), defects: rows.length, file: fileRow ? fileRow.檔名 : '' };
  } finally { lock.releaseLock(); }
}
/** 紀錄表原檔資料夾（擁有者雲端硬碟；第一次自動建立） */
function djFolder_() {
  let folder = prop_('DJ_FOLDER_ID');
  if (!folder) {
    const r = driveFetch_('https://www.googleapis.com/drive/v3/files?fields=id', {
      method: 'post', contentType: 'application/json',
      payload: JSON.stringify({ name: '督導紀錄檔案', mimeType: 'application/vnd.google-apps.folder' })
    });
    folder = JSON.parse(r.getContentText()).id;
    setProp_('DJ_FOLDER_ID', folder);
  }
  return folder;
}
